pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {LRTDepositPool} from "../src/LRTDepositPool.sol";

contract InvMutTest is Test {
    LRTDepositPool c;
    function setUp() public { c = new LRTDepositPool(); }
    function testFuzz_property(uint8 choice) public {
        vm.assume(choice < 100);
        bool pausedState = c.paused();
        assertTrue(!pausedState, "paused() should return false for uninitialized contract");
    }
}
